pragma solidity >=0.8.0;

contract IntDivLayoutUncheckedReorder {
    int256 public min256;
    int16 public min16;
    uint8 public bump;
    uint256 public count;

    constructor() {
        min256 = type(int256).min;
        min16 = type(int16).min;
        bump = 1;
    }

    function div256() public returns (int256) {
        int256 r = min256 / int256(-1);
        unchecked { count++; }
        return r;
    }

    function div16() public returns (int16) {
        int16 r = min16 / int16(-1);
        unchecked { count++; }
        return r;
    }

    function touchBump(uint8 v) public {
        bump = v;
        unchecked { count++; }
    }
}
